/* ============================================================
   Bundled fonts.
   ------------------------------------------------------------
   @font-face does not work on this page: the WebView serves the app
   from file:///android_asset/ and drops the face however it is
   referenced, so the bytes are registered from here instead.

   The mushaf face is TTF rather than WOFF2 on purpose. WOFF2 needs a
   Brotli decoder to unpack; TTF needs nothing, so it removes the last
   way the bytes could arrive intact and still fail to become a font.

   Two routes are tried per face — straight from an ArrayBuffer, then
   behind a blob: URL, which is same-origin and so not subject to the
   file:// restriction. Everything is wrapped: a throw here once left
   the status unset, which the reader read as success.

   Generated file: do not hand-edit.
   ============================================================ */

var BUNDLED_FONTS = [
    { family: 'UthmanicHafs', weight: '400', mime: 'font/ttf', data: '' },
    { family: 'Thmanyah', weight: '300', mime: 'font/woff2', data: '' },
    { family: 'Thmanyah', weight: '400', mime: 'font/woff2', data: '' },
    { family: 'Thmanyah', weight: '700', mime: 'font/woff2', data: '' },
    { family: 'Thmanyah', weight: '900', mime: 'font/woff2', data: '' }
];

var fontLoadStatus = 'لم يبدأ';
var bundledFontsReady;

(function () {
    function bytes(b64) {
        var bin = atob(b64);
        var buf = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
        return buf;
    }

    function viaBuffer(f) {
        return new FontFace(f.family, bytes(f.data).buffer,
            { weight: f.weight, style: 'normal' }).load();
    }

    function viaBlob(f) {
        var url = URL.createObjectURL(new Blob([bytes(f.data)], { type: f.mime }));
        return new FontFace(f.family, 'url(' + url + ')',
            { weight: f.weight, style: 'normal' }).load();
    }

    try {
        if (typeof FontFace === 'undefined' || !document.fonts) {
            fontLoadStatus = 'المتصفح لا يدعم تحميل الخطوط';
            bundledFontsReady = Promise.resolve(false);
            return;
        }

        var failures = [];
        var jobs = BUNDLED_FONTS.map(function (f) {
            return viaBuffer(f)
                .catch(function () { return viaBlob(f); })
                .then(function (face) { document.fonts.add(face); return true; })
                .catch(function (e) {
                    failures.push(f.family + '/' + f.weight + ': '
                        + (e && e.message ? e.message : e));
                    return false;
                });
        });

        bundledFontsReady = Promise.all(jobs).then(function (r) {
            var ok = r.every(Boolean);
            fontLoadStatus = ok ? 'تم التسجيل' : ('فشل ' + failures.join(' | '));
            return ok;
        });
    } catch (e) {
        fontLoadStatus = 'خطأ: ' + (e && e.message ? e.message : e);
        bundledFontsReady = Promise.resolve(false);
    }
})();

/**
 * Is a family actually drawing text? Registering a face and having it applied
 * are different things; this measures a string in the family against the same
 * string in a known fallback, so a difference means the real face is in use.
 */
function fontIsRendering(family) {
    try {
        var probe = document.createElement('span');
        probe.textContent = 'الحمد لله رب العالمين ١٢٣';
        probe.style.cssText =
            'position:absolute;left:-9999px;top:-9999px;font-size:80px;white-space:nowrap;';
        document.body.appendChild(probe);
        probe.style.fontFamily = 'monospace';
        var base = probe.getBoundingClientRect().width;
        probe.style.fontFamily = "'" + family + "', monospace";
        var test = probe.getBoundingClientRect().width;
        document.body.removeChild(probe);
        return Math.abs(test - base) > 1;
    } catch (e) {
        return false;
    }
}
